# -*- coding: utf-8 -*-
# 센서별 서술형 카드. 【 】 = 강의자료 원문 표현, 〔 〕 = 작년 기출 교수님 답안 표현
W1='Week1 센서의 기초'; W21='Week2 가스센서01'; W22='Week2 가스센서02'; W3='Week3 자기센서01'; W4='Week4 자기센서02'; W5='Week5 속도센서·금속탐지기'; W6='Week6 가속도·진동센서'
E = {}
def add(cid, title, kws, first, src, keys, qa):
    E[cid]=dict(title=title, kws=kws, first=first, src=src, keys=keys, qa=qa)

# ───────── Ⅰ 센서의 기초 (3) ─────────
add('3-A','감도 · 분해능 · 측정하한치(MDL)',['감도','분해능','MDL','3σ'],
 '감도 = 교정 직선 기울기 · 분해능 = Noise ÷ 감도 · MDL = 3σ ÷ 감도 (둘 다 입력 단위)',
 [(W1,'p.11–12','감도 · 순간/평균/선형화 감도'),(W1,'p.14','분해능 = Noise/Sensitivity'),(W1,'p.20','MDL = 3σ/S, 평가과정')],
 [('감도 S','S = Δy/Δx = 교정 직선의 기울기'),('분해능','Noise ÷ Sensitivity → 입력 단위'),('MDL','3σ ÷ S → 입력 단위'),('비선형 센서','순간 감도(접선 기울기) · 평균 감도(구간) · 선형화 감도(전체 직선 근사)')],
 [('감도(sensitivity)를 정의하라.','【입력신호의 미소 변화에 대한 출력신호의 미소 변화의 비율】이며, 【Calibration plot에서 기울기 S】가 감도이다. S = Δy/Δx.','입력을 조금 바꿨을 때 출력이 얼마나 많이 바뀌나예요. 그래프가 가파를수록 민감한 센서예요.'),
  ('분해능(resolution)을 정의하고 단위를 말하라.','【센서가 검출할 수 있는 최소 입력 변화량】이며 【분해능 = Noise/Sensitivity】로 구한다. 노이즈는 출력 단위, 감도는 출력/입력 단위이므로 【분해능의 단위는 입력량의 단위】이다.','출력이 노이즈만큼 흔들리면 그보다 작은 변화는 구별 못 해요. 그 노이즈를 입력 크기로 바꾼 게 분해능이에요.'),
  ('측정하한치(MDL)를 정의하고 평가 과정을 설명하라.','【센서가 배경잡음과 구별하여 검출할 수 있는 최소 입력값】. 【입력이 없는 상태에서 측정한 출력 노이즈의 표준편차 σ】와 감도로 【MDL = 3σ/S】. 평가: 【배경 노이즈 측정 → 반복 분석 → 노이즈 크기의 약 3배에 해당하는 출력값을 detection limit으로 정의】.','"노이즈의 3배는 넘어야 진짜 신호"라는 약속이에요. 3σ가 출력 단위라 감도로 나눠 입력 단위로 바꿔요.'),
  ('비선형 센서는 왜 감도를 한 값으로 쓸 수 없는가? 대안 세 가지는?','【비선형 센서에서는 감도가 일정하지 않기 때문에 한 개의 값으로 표현할 수 없다】. 【순간 감도(특정 지점 접선 기울기)】, 【평균 감도(특정 구간 평균 기울기)】, 【선형화 감도(전체 범위를 직선으로 근사한 기울기)】로 표현한다.','곡선은 위치마다 기울기가 달라요. 한 점에서 재거나, 구간으로 재거나, 통째로 직선 하나로 보거나 셋 중 하나를 골라요.')])

add('3-B','선형성 · R² · 반복성 · 재현성 · 정확도',['선형성 %FS','R²','repeatability','정확도'],
 '선형성 = 최대편차/정격 × 100 [%FS] · R² = 1 − SS_res/SS_tot [단위 없음] · 정확도 = 100 − 오차율',
 [(W1,'p.21','선형성 %FS'),(W1,'p.22–24','R² · Linearity vs R²'),(W1,'p.25','Repeatability, Reproducibility'),(W1,'p.26','정확도 = 100 − 오차율')],
 [('선형성','최대출력편차 ÷ 정격출력 × 100 [%FS]'),('R²','1 − SS_res/SS_tot, 1에 가까울수록 직선에 잘 맞음'),('오차율','|xₘ − xₜ| ÷ xₜ × 100'),('반복성/재현성','단기·동일조건 / 장기·다른 사람·다른 실험실')],
 [('선형성(linearity)을 정의하고 단위를 쓰라.','【센서의 특성 곡선이 이상적인 직선관계(기준직선)로부터 벗어남의 정도】. 【선형성 = 최대출력편차/정격출력 × 100 %】, 단위는 【%FS (full scale)】.','이상적인 직선에서 가장 많이 벗어난 곳이 전체 범위의 몇 %인지예요.'),
  ('선형성과 결정계수 R²의 차이는?','【Linearity → 이상적인 기준직선을 기준으로 실제 측정값들이 그 관계를 얼마나 잘 따르는지 평가 [%FS]】. 【R² → 실제 데이터로 얻어진 회귀직선이 실제 Y의 변동을 얼마나 잘 설명하는지 평가 [no unit], 값이 1에 가까울수록 일치도가 높음】.','선형성은 "이상 직선" 기준, R²은 "데이터로 구한 직선" 기준이에요. 하나는 %, 하나는 단위 없는 0~1 숫자예요.'),
  ('반복성(repeatability)과 재현성(reproducibility)의 차이는?','【Repeatability: 동일조건하에서 동일방법으로 단기간에 연속 측정할 때 측정값들이 서로 얼마나 일치하는가】. 【Reproducibility: 장기간에 걸쳐 측정하거나 다른 사람·다른 실험실에서 측정될 때 측정값 사이에 일치하는 정도】.','반복성은 "내가 지금 연속으로 재도 같나", 재현성은 "남이 다른 날 다른 곳에서 재도 같나"예요.'),
  ('정확도(accuracy)를 정의하고 참값은 어떻게 얻는가?','【센서 측정값이 참값에 얼마나 가까운가를 나타내는 척도】, 【정확도[%] = 100 − 오차율】, 오차율 = |xₘ − xₜ|/xₜ × 100. 참값은 【상업용 최고의 센서 측정값】이나 【신뢰할 수 있는 reference value(GC 등)】, 또는 교정 직선과 비교해 얻는다.','기출 1-iii에서는 교정 직선을 참값으로 보고 입력 기준(7.36 vs 7)으로 비교했어요.')])

add('3-C','감도 드리프트 · 응답시간 · 주파수 특성',['sensitivity drift','90 %','상대 변화율'],
 '드리프트 = 기울기가 시간·환경에 따라 변함 → 재교정 · 응답시간 = 포화값 90 % 도달 시간 · 출력은 초기값 대비 %로 비교',
 [(W1,'p.13','Sensitivity drift 원인·제거'),(W1,'p.29','응답시간 90 %'),(W1,'p.30','주파수 특성 · 왜 %를 쓰는가')],
 [('드리프트 원인','감지물질 열화(상변화·poison gas·산화·부식·노화) / 회로 열화(증폭기·ADC·기준전압) / 열팽창·패키지 응력'),('제거','정기적 re-calibration'),('응답시간','포화값의 90 % 도달 시간'),('비교 기준','절대 변화량 ✗ → 초기값 대비 상대 변화량(%) ○')],
 [('Sensitivity drift란 무엇이며 원인과 제거 방법은?','【센서의 입력–출력 변환 특성에서 감도(Slope)가 시간 또는 환경 조건에 따라 변화하는 현상】으로 【Calibration curve의 기울기가 변화】한다. 원인: 【감지 물질 내 상변화, poison gas의 흡착, 산화, 부식, 노화】, 【증폭기·ADC·기준전압 등 전자회로의 장기적 열화】, 【열팽창이나 패키지 응력】. 제거: 【정기적인 re-calibration을 통해 현재 감도 특성을 재평가하고 calibration plot을 갱신】.','센서가 늙으면 같은 입력에도 출력이 예전과 달라져요. 그래서 가끔 다시 교정해요.'),
  ('응답시간(response time)의 정의는?','【Saturation 값의 90 %에 도달하는 시간】. 회복시간은 자극 제거 후 원래 수준으로 돌아오는 시간.','가스를 넣고 출력이 거의 다(90 %) 올라올 때까지 걸리는 시간이에요.'),
  ('센서 출력을 비교할 때 절대 변화량이 아니라 %를 쓰는 이유는?','【센서의 출력값은 절대적인 변화량만 비교하면 안 되고, 초기값에 대한 상대적인 변화량(%)으로 비교해야 한다】. 【서로 다른 센서나 서로 다른 측정 조건에서도 센서의 성능을 공정하게 비교하기 위해서】이다. A/cm², C/cm²를 쓰는 것도 같은 이유.','초기 저항이 100 Ω인 센서와 1000 Ω인 센서는 같은 가스에도 ΔR 크기가 달라요. 비율로 봐야 공평해요.')])

add('3-D','센서 정의 · 임피던스 매칭 이유',['transducer','maximum power','R_L = R_S'],
 '센서 = 외부 자극 → 전기 신호 변환 소자(transducer) · 부하에 최대 전력 = R_L = R_S + 허수부 0',
 [(W1,'p.8','센서의 정의 · 센서는 transducer'),(W1,'p.9','센서시스템 구조'),(W1,'p.31–32','임피던스 매칭 · R_L = R_S 유도')],
 [('센서','외부 자극(stimulus) → 전기 신호'),('자극','검출하려는 양·특성·상태'),('최대 전력 전달','P_L = V²/(R_S²/R_L + 2R_S + R_L) 최대 ⇔ R_L = R_S'),('허수부','반대 부호 소자를 직렬로 상쇄')],
 [('센서를 정의하라.','【외부 자극(stimulus)을 받아 이를 전기 신호로 변환하는 소자(센서는 transducer이다)】. 【외부 자극: 검출 또는 측정하고자 하는 양(Quantity), 특성(Property), 상태(Condition)】.','온도·가스·자기장처럼 사람이 정확히 못 느끼는 것을 전기 신호로 바꿔 주는 부품이에요.'),
  ('임피던스 매칭이 왜 필요하며 조건은?','【전력공급을 최대로 하려면 임피던스 매칭이 요구된다】. P_L = V²/(R_S²/R_L + 2R_S + R_L)에서 분모가 최소일 때 P_L이 최대이고, R_L로 미분해 0이 되는 조건이 【R_S = R_L】이다. 부하에 허수부가 있으면 반대 부호의 리액턴스를 직렬 연결해 0으로 만든다.','전원 쪽 저항과 부하 저항이 같을 때 부하가 전력을 가장 많이 받아요. 허수부는 먼저 지워야 해요.')])

# ───────── Ⅱ 가스센서 (9) ─────────
add('9-A','Pd 수소센서 원리 · Pd–Ni 합금',['Pd','PdHₓ','격자 팽창','Ni 4~8 %'],
 'H₂ 흡착 → 해리 → Pd 내부 확산 → PdHₓ → 전도도 변화 → 저항 변화 · Ni 합금 = 팽창·상전이 억제',
 [(W21,'p.7','수소 특성(4~75 % 폭발), 응용'),(W21,'p.9','Pd 감지 흐름'),(W21,'p.10','Pd 팽창 10.9 %, Pd–Ni 합금'),(W21,'p.16–18','표면적/부피비, 구동온도, 습도')],
 [('감지 흐름','H₂ 표면 흡착 → 해리 → 원자 H 확산·흡수 → PdHₓ → 전기전도도 변화 → 저항 변화'),('Pd 문제','부피 최대 약 10.9 % 팽창 → 비선형·히스테리시스·crack'),('해결','Pd–Ni (Ni 4~8 %) → 팽창·상전이 억제, 단 감도 감소'),('온도','흡착↑ vs 탈착↑ trade-off → 최적 구동온도, 마이크로히터로 유지')],
 [('Pd 저항형 수소센서의 감지 원리를 순서대로 설명하라.','【H₂ 표면 흡착 → H₂ 해리 → 원자상 H의 Pd 내부 확산·흡수 → PdHₓ 형성 → 전자구조 및 전기전도도 변화 → 전기저항 변화】. Pd는 【수소에 대한 높은 흡수능 및 용해도를 가지며 상온에서 수소 감지가 가능】하다.','팔라듐은 수소를 스펀지처럼 빨아들여요. 수소가 들어가면 전기가 흐르는 성질이 변해서 저항으로 읽어요.'),
  ('순수 Pd의 문제점과 Pd–Ni 합금을 쓰는 이유는?','수소가 Pd의 【interstitial site에 들어가면서 격자상수가 증가하고 부피가 최대 약 10.9 %까지 팽창】 → 반복 팽창/수축으로 【비선형성, 히스테리시스, 장기 신뢰성 저하, crack·blistering·delamination】. 【Pd에 소량의 Ni(약 4~8 %)를 첨가】하면 【격자 팽창 및 상전이를 억제】하여 히스테리시스와 기계적 손상이 줄고 안정성이 향상되지만 【감도가 감소할 수 있음】.','부풀었다 줄었다를 반복하면 갈라져요. 니켈을 조금 섞으면 덜 부풀지만 민감도는 조금 떨어져요.'),
  ('구동온도를 높이면 생기는 trade-off와 마이크로히터를 쓰는 이유는?','온도↑ → 【H₂ dissociation and adsorption kinetics↑, H diffusion↑】 그러나 【동시에 H₂ desorption rate↑】 → 【adsorption/infiltration과 desorption 사이의 trade-off】 → 【Optimal operating temperature가 필요】. 【Microheater를 이용하여 일정한 operating temperature 유지】, 【operating temperature는 ambient temperature보다 높게 설정】해 【ambient 변화에 관계없이 stable and reproducible sensor response 확보】.','뜨거우면 수소가 잘 들어가지만 잘 빠져나가기도 해요. 딱 좋은 온도를 히터로 고정해요.'),
  ('습도가 수소센서에 미치는 영향은?','【H₂O molecules can adsorb on the sensor surface and form hydroxyl (OH) species】 → 【상대습도↑ → H₂O/OH surface coverage↑ → fewer active sites available for H₂ adsorption】 → 【Reduced H₂ infiltration → Decreased sensitivity and increased baseline drift】.','물 분자가 자리를 먼저 차지해서 수소가 붙을 자리가 줄어요.')])

add('9-B','4-wire 이유 · 브리지 설계 · 제작',['4-wire','전압강하','R₀','Al₂O₃'],
 '4선 = 전류선/전압선 분리, 전압선 I = 0 → 선 저항 영향 제거 · 브리지 = 같은 재료·같은 R₀ · Al₂O₃ = 비감지 영역 수소 차단',
 [(W21,'p.12–13','Why use four wires'),(W21,'p.24–25','Wheatstone Bridge · R₀ 영향'),(W21,'p.26–27','센서의 제작 · Al₂O₃ 삽입'),(W21,'p.29','초기화')],
 [('4-wire 목적','긴 Line 저항에 의한 전압강하 제거'),('방법','정전류원 + 고입력임피던스 전압 측정 → Rₛ = Vₛ/Iₛ'),('브리지','공통 변화 보상 · ΔR → 차동 출력'),('R₀ 다른 센서 비교','Normalized response ΔR/R₀ × 100 %')],
 [('저항형 센서에서 4-wire 방식을 쓰는 이유와 원리는?','【긴 Line의 저항에 의한 전압강하를 제거(최소화)하기 위함】. 【전류 공급선과 전압 측정선을 분리】하고 【정전류원으로 일정한 전류 I를 인가】, 【센서 양단의 전압 V를 측정】해 【Rₛ = Vₛ/Iₛ】로 계산. 【전압 측정단은 매우 높은 입력 임피던스를 가지므로 전류가 거의 흐르지 않고 전압 측정선의 저항에 의한 전압강하가 거의 발생하지 않는다】. 【Line 저항은 온도에 의해서도 변화】하므로 중요.','전압을 재는 선에는 전류가 안 흐르니까, 그 선이 길어도 손해가 없어요.'),
  ('Wheatstone bridge의 역할과 저항 설계 조건은?','【환경 변화(특히 temperature)에 의한 공통 저항 변화를 보상】하고 【작은 저항 변화 ΔR를 차동 출력으로 변환하여 높은 sensitivity 확보】. 【Sensing resistor와 reference resistor를 동일/유사한 재료 및 저항 특성으로 설계 → 최대 temperature compensation】. 【두 저항이 동일한 비율로 변화하면 bridge ratio가 유지되어 V_out의 temperature dependence가 최소화】.','〔온도, 습도 등 외부 간섭요소에 의한 변화분을 최소화〕가 작년 교수님 표현이에요.'),
  ('초기 저항 R₀가 다른 센서들의 감도는 어떻게 비교하는가?','【세 센서는 서로 다른 R₀을 가지므로 absolute output[V]만으로 직접 비교하기 어려움】 → 【Normalized response(ΔR/R₀×100 %)를 사용하여 상대적인 저항 변화율을 비교】.','출력 전압 크기는 R₀에 따라 달라지니 비율로 비교해요.'),
  ('센서 제작에서 Al₂O₃ passivation층을 넣는 이유와 Pd를 마지막에 증착하는 이유는?','【수소는 매우 작은 원자이므로 일부 재료 내부로 확산·침투할 수 있음】 → 【원하지 않는 영역으로의 H₂/H 확산을 방지하기 위해 Al₂O₃ passivation layer를 적용】 → 【비감지 영역의 수소 침투를 최소화하고 sensing area를 선택적으로 정의】. Pd는 【외부 간섭 및 공정 영향을 최소화하기 위해 마지막 단계에 증착】.','수소는 어디든 스며드니 감지할 곳만 열어 두고 나머지는 덮어요.')])

add('9-C','Baseline drift · 선택성 · 표면적/부피비',['baseline drift','selectivity','cross-sensitivity','surface/volume'],
 'drift 원인 4종(환경·표면·탈착·전자) → 보상·재교정·보정 알고리즘 · 선택성 ↑ 4가지 · 표면적↑ = 감도↑·응답↑ but 균일성↓',
 [(W21,'p.19–21','Baseline drift 원인·해결·보정법'),(W21,'p.32–33','선택성 · 향상 방법 4가지'),(W21,'p.16','Large surface to volume ratio')],
 [('drift 정의','기준 출력(baseline)이 시간에 따라 점진적으로 변함'),('원인','환경(온·습·압) / 표면(오염·노화) / 불완전 탈착 / 전자회로(ADC offset 등)'),('선택성 향상','감지물질 선택 · 구동온도 최적화 · 선택성 필터 · 센서 어레이+패턴인식'),('표면적/부피비↑','active site↑, 응답↑, 감도↑ / 대량생산·균일성·노이즈·안정성 문제')],
 [('Baseline drift의 정의, 원인, 해결 방법은?','【센서의 기준 출력(baseline)이 시간에 따라 점진적으로 변하는 현상】. 원인: 【환경적 요인(온도·습도·압력)】, 【표면/재료적 요인(오염, 잔류 가스, aging)】, 【탈착 불완전】, 【전자적 요인(전원 불안정, ADC offset, circuit drift)】. 해결: 【Temperature/Humidity compensation, Periodic calibration, Baseline correction 알고리즘, aging/pre-conditioning, 재료·회로 개선】.','가스가 없어도 기준값이 슬금슬금 움직여요. 측정 전 N₂에서 초기화하고, 주기적으로 교정하고, 소프트웨어로 보정해요.'),
  ('선택성(selectivity)이란 무엇이며 어떻게 평가하는가?','【다양한 가스 및 환경 요인 중 target gas에 선택적으로 반응하는 센서의 특성】. 【실제 사용환경에서 공존할 가능성이 있는 interfering gases와의 교차감응(cross-sensitivity)을 평가】. H₂ 센서는 【O₂, N₂뿐만 아니라 CO, CO₂, CH₄, NH₃, H₂O 등의 영향】을 고려.','우리 가스에만 반응하고 다른 가스에는 반응 안 하는 정도예요.'),
  ('선택성을 높이는 방법 4가지를 쓰라.','① 【Optimal sensing material selection】 ② 【Operating temperature optimization(온도에 따라 각 가스의 adsorption·dissociation·reaction kinetics가 다름)】 ③ 【Selective porous membrane / filter】 ④ 【Sensor Array + Pattern Recognition(여러 센서의 response pattern 분석)】.','재료·온도·필터·여러 개 묶기, 네 가지예요.'),
  ('감지물질의 표면적/부피비가 클 때 장단점은?','장점: 【Large gas-accessible surface area, More active sites, Fast response/recovery, High sensitivity】. 단점: 【Difficult mass production, Poor device-to-device uniformity, Increased noise, Long-term stability issues】.','나노구조처럼 표면이 넓으면 민감하지만 똑같이 만들기 어렵고 노이즈가 커요.')])

add('9-D','반도체식 가스센서 · 고온 · 나노파티클',['n형 산화물','depletion','200~400 °C','Schottky'],
 'n형: 환원성 → 전자 반환 → 저항↓ · 산화성 → 전자 포획 → 저항↑ · 고온 = 반응 활성화 · NP = 전기적+화학적 증감',
 [(W22,'p.2','반도체식 가스센서 개요'),(W22,'p.3–4','환원성/산화성 가스 검출 메커니즘'),(W22,'p.5','높은 구동온도가 필요한 이유'),(W22,'p.7','나노파티클 증착 이유')],
 [('재료','ZnO, WO₃, SnO₂ 등 대부분 n형'),('n형+환원성','흡착 산소와 반응 → 전자 반환 → depletion↓ → 저항↓'),('n형+산화성','전자 포획 → depletion↑ → 저항↑'),('고온 이유','산소 흡착 활성화 · 반응 촉진 · 흡탈착 속도↑'),('NP','electrical(Schottky) + chemical(촉매) sensitization')],
 [('n형 산화물반도체 센서가 환원성 가스를 검출하는 메커니즘을 설명하라.','【n-type 산화물반도체가 공기 중 산소에 노출되면 산소 분자가 표면에 흡착하면서 전자를 포획 → electron depletion layer 형성】 → 【potential barrier 증가 → 초기 저항 R₀】. 【환원성 가스가 흡착된 산소종과 반응하여 CO₂, H₂O 등을 생성하면서 포획되어 있던 전자를 되돌려줌 → 전자 농도 증가 → depletion layer 감소 → potential barrier 감소 → 전기저항 감소】.','산소가 전자를 잡아 두고 있다가, 수소가 와서 산소와 반응하면 전자가 풀려나 저항이 내려가요.'),
  ('산화성 가스(NO₂)일 때는 어떻게 되는가?','【NO₂: 산화성 가스 → electron acceptor】. 【표면에 흡착되면 전자를 포획하여 n-type의 전자 농도를 감소 → depletion region 증가 → potential barrier 증가 → 센서 저항 증가】.','전자를 더 빼앗아 가니 저항이 올라가요. p형이면 반대예요.'),
  ('반도체식 가스센서에 200~400 °C의 높은 구동온도가 필요한 이유는?','【표면에서 산소 흡착 활성화】, 【타깃 가스–흡착 산소 반응 촉진】, 【흡착/탈착 속도 향상】 → 【Active site 증가 → 감도 향상】. 따라서 【소형화된 센서에서는 마이크로히터 집적이 필요】.','뜨거워야 표면 반응이 빨라져요.'),
  ('산화물반도체 표면에 금속 나노파티클을 증착하는 이유 두 가지는?','【Electrical sensitization: Metal NP 증착 → Schottky junction 형성 → depletion region/barrier 형성 → 전기적 신호 변화 증폭】. 【Chemical sensitization: NP의 catalytic activity↑ → reactive oxygen species↑ → gas–oxygen reaction↑ → 감도↑】.','금속 알갱이가 전기 신호를 키우고(전기적), 반응을 도와요(화학적).')])

add('9-E','마이크로히터 Pt · 열평형 · GC 원리',['Pt','Joule','열평형','GC retention time'],
 'Pt = 고온 안정·내산화·저항 안정 · 발열 = 방열 → 온도 일정 · GC = stationary phase 상호작용 차이로 분리',
 [(W22,'p.13','Microheater 요구사항 · Pt · 열 생성'),(W22,'p.15','열평형'),(W22,'p.19','주변온도 변화 시 전류 조절'),(W22,'p.30–35','GC 동작원리 · flow 최적화')],
 [('히터 조건','히터 온도 > 주변 온도'),('Pt 이유','고온 안정 · 내산화 · 저항–온도 관계 안정'),('일정 온도','발열(VI) = 방열(전도+대류+복사)'),('GC','상호작용 강 = 느림, 약 = 빠름 → retention time으로 식별')],
 [('마이크로히터 재료로 Pt를 쓰는 이유와 히터 온도 조건은?','【높은 온도에서 안정성이 높음】, 【고온에서도 산화에 대한 내성이 우수】, 【전기저항의 온도 의존성이 비교적 안정적이어서 온도 측정/제어에도 활용 가능】(Pt 녹는점 1768 °C). 【마이크로히터의 온도는 주변 온도보다 높게 유지되어야 함】, 그렇지 않으면 【열전달 방향이 달라져 센서 표면 온도가 주변 온도의 영향을 크게 받음】.','오래 뜨겁게 써야 하니 안 녹고 안 녹슬고 저항이 믿을 만한 백금을 써요.'),
  ('일정 전압에서 온도가 일정해지는 이유와, 주변 온도가 변할 때 어떻게 목표 온도를 유지하는가?','【온도가 상승하면 열전도·대류·복사에 의한 열손실이 증가】 → 【발열량과 방열량이 같아지는 지점 → 열평형 → 온도 일정】. 【주변 온도가 낮아지면 온도차가 증가하여 열손실이 증가 → 더 많은 열을 생성해야 하므로 히터 전류를 증가】, 반대면 감소. 〔열의 생성 = 열의 방사가 평형을 이루는 steady-state〕.','욕조에 물을 틀어 두면 넘치는 양과 들어오는 양이 같아지며 수위가 멈추는 것과 같아요.'),
  ('Gas chromatography의 분리 원리를 설명하라.','【시료가 carrier gas에 실려 column을 통과하며 성분마다 stationary phase와 상호작용이 다름】. 【강하게 상호작용하는 가스는 느리게, 약하게 상호작용하는 가스는 빠르게 이동】 → 【각 가스가 다른 속도로 이동해 분리】 → 【retention time으로 검출·식별】. 상호작용은 【화학 반응이 아닌 물리적 흡착·탈착 평형】.','긴 관에 섞인 가스를 흘리면 성분마다 나오는 시간이 달라 하나씩 분리돼요.'),
  ('Carrier gas 유량이 너무 빠르거나 느리면 어떤 문제가 생기는가?','빠름: 【analyte와 stationary phase의 상호작용 시간이 부족 → 분리능(resolution) 감소】. 느림: 【longitudinal diffusion 증가 → peak broadening, 분석 시간 증가】. 【최적 flow rate에서 column efficiency가 최대】.','너무 빠르면 안 갈라지고, 너무 느리면 봉우리가 퍼져요.')])

# ───────── Ⅲ 자기센서 (11) ─────────
add('11-B','홀 센서 구동 회로 · 재료 · 구조',['정전류','정전압','InSb','GaAs','십자형'],
 '정전류 = 안정·직선성 but 복잡 · 정전압 = 간단 but μ 온도 의존 · InSb 고감도 / GaAs 온도 안정 · 십자형 = f_H ≈ 1',
 [(W3,'p.22','Hall sensor materials'),(W3,'p.23–25','형상계수 f_H, 십자형'),(W3,'p.27–29','정전류/정전압 구동, 온도의존성'),(W3,'p.31','Offset 원인')],
 [('정전류','V_H = R_H·I·B/t → 직선성 우수, 저항·온도 영향 적음 / 회로 복잡, 전류 노이즈'),('정전압','V_H = μ(w/l)·V·B → 간단·저가 / 저항 변화·전원 오차·μ 온도 의존'),('재료','InSb: 고이동도 → 고감도 / GaAs: 고온 안정'),('형상계수','l/w > 3 → f_H ≈ 1, 십자형 실용')],
 [('홀 센서의 정전류 구동과 정전압 구동의 장단점을 비교하라.','정전류: 【직선성 우수】, 【센서 저항 및 온도 변화의 영향을 상대적으로 줄일 수 있음】, 【V_H 안정성 높음】 / 【회로가 복잡하다 → 비용증대】, 【전류의 노이즈가 홀 전압에 영향】. 정전압: 【회로가 간단하고 비용이 낮음】 / 【센서 저항이 변화하면 전류가 변화 → V_H 영향】, 【전원 전압의 오차가 V_H에 영향】, 【V_H의 온도 의존성이 크다 → 이동도의 온도 의존성 때문】.','정전류는 비싸지만 흔들림이 적고, 정전압은 싸지만 온도에 흔들려요.'),
  ('홀 센서 재료로 InSb와 GaAs의 특징은?','【Higher mobility and larger energy bandgap are preferred】. 【InSb: Energy bandgap 매우 작지만 high mobility → high sensitivity】, 【GaAs: high temperature stability】. InSb는 【정전압 구동회로가 유리】.','InSb는 민감, GaAs는 튼튼이에요.'),
  ('실용 홀 센서가 십자형(cross-shaped) 구조인 이유와 형상계수의 의미는?','이상적 홀 전압식은 【무한히 긴 홀 소자】 기준이라 실제는 【형상계수 f_H(0~1)】를 곱한다. 【f_H는 l/w의 함수이며 l/w ≫ 3 범위에서는 거의 1】. 【제작하기가 훨씬 더 용이한 십자형 구조로부터 동일한 형상계수 값을 얻을 수 있기 때문】에 실용 센서는 십자형이며 【형상계수 ~1, 제작용이, 전극간 short 방지】.','길쭉하게 만들어야 식대로 나오는데, 십자 모양이면 작아도 같은 효과예요.'),
  ('홀 전압 offset의 원인은?','【전극 위치의 비대칭, 센서 형상의 불균일, 접촉저항 차이, 전극 크기 차이】. 【단순한 offset은 보정하여 제거할 수 있지만 온도·전류·자기장·증폭기 drift 등에 따라 offset이 변할 수 있다】.','자기장이 없어도 0이 아닌 출력이 나오는 게 offset이에요. 만드는 과정의 작은 비대칭 때문이에요.')])

add('11-C','AMR · 바버 폴 · 자성체 기초',['AMR','cos²θ','45°','퍼말로이','Curie'],
 'I ∥ M 저항 최대, ⊥ 최소 · R = R⊥ + ΔR cos²θ · 45° 바버 폴 = 직선 영역 · 브리지 = 감도↑ drift↓',
 [(W3,'p.4','자성체 종류'),(W3,'p.10','Curie 온도'),(W3,'p.11','자기센서 종류(약·중·강자계)'),(W4,'p.3–6','AMR 원리·식'),(W4,'p.7–9','barber pole · bridge'),(W4,'p.10','특징·한계')],
 [('AMR','전류와 자화가 평행이면 저항 최대, 수직이면 최소'),('식','R(θ) = R⊥ + ΔR cos²θ, θ = 45° 전후 직선 영역'),('바버 폴','Al 단락 바 45° → 유효 전류 방향 45°'),('자성체','강자성 Fe·Ni·Co / 페리 Fe₃O₄ / 상자성 Al·Pt / 반자성 Cu·Ag·Au·H₂O'),('Curie','Fe 770, Co 1127, Ni 358 °C')],
 [('이방성 자기저항(AMR) 효과를 설명하라.','【Ferromagnetic 물질에서 전류(I)의 방향과 자화(M)의 방향이 서로 평행일 때 저항이 최대로 되고, 서로 수직한 경우 최소로 되는 현상】. 원인: 【스핀–궤도 결합(SOC)에 의해 전도전자의 산란 조건이 자화 방향에 의존】. 【R(θ) = R⊥ + ΔR cos²θ】, 【θ = 45°를 전후로 직선영역이 존재】. 저항 변화는 수 %.','자석 방향과 전류 방향이 나란하면 전자가 더 많이 부딪혀 저항이 커져요.'),
  ('Barber pole을 45°로 형성하는 이유는?','【Al 단락 바를 약 45° 방향으로 형성】 → 【Al은 NiFe에 비해 전기저항이 매우 낮아】 【NiFe 내부의 유효 전류 방향이 약 45°】 → 【자화 방향과 유효 전류 방향이 약 45°를 이루도록 설정 → 자기장 변화에 대해 저항 변화가 선형적으로 나타나기 유리】.','cos²θ 곡선은 0° 근처가 평평해서 반응이 없고, 45° 근처가 직선이라 거기서 쓰려고 전류를 비스듬히 만들어요.'),
  ('AMR 소자 4개로 휘트스톤 브리지를 구성하는 이유는?','【두 소자의 바버 폴 방향은 +45°, 다른 두 소자는 −45°】 → 자계에 대해 【R₁·R₃는 저항 감소, R₂·R₄는 저항 증가】 → 【센서의 온도 드리프트를 감소시키고 감도를 증가】.','반대로 움직이는 저항을 짝지으면 출력이 두 배가 되고 온도는 지워져요.'),
  ('자성체의 종류와 큐리 온도를 설명하라.','【강자성체: Ni, Fe, Co】, 【페리자성체: ferrite(Fe₃O₄)】, 【상자성체: Al, Pt, Cr, O₂】, 【반자성체: Cu, Ag, Au, H₂O — 외부 자기장과 반대 방향으로 약간 자화】. 【온도가 상승함에 따라 자기 모멘트 배열이 흐트러져 자성이 상실되는 온도가 큐리 온도: Fe 770 ℃, Co 1127 ℃, Ni 358 ℃】.','자석이 되는 세기 순서로 강자성 > 페리 > 상자성, 반자성은 반대로 약하게 밀려요.')])

add('11-D','GMR · 스핀 밸브 · SQUID',['GMR 70 %','평행/반평행','spin valve','Josephson','Φ₀'],
 'GMR: 평행 = 산란 적음 = 저항 최소, 반평행 = 최대 · 스핀 밸브 = 고정층 + 자유층 → 비대칭 · SQUID: 전압이 Φ₀ 주기로 진동',
 [(W4,'p.13','GMR 1988 · 70 %'),(W4,'p.15–17','Spin-dependent scattering · 두께 < 10 nm'),(W4,'p.18–21','다층막 · 스핀 밸브'),(W4,'p.30–32','초전도체 · 조셉슨 접합 · DC 조셉슨'),(W4,'p.33–37','RF/DC SQUID · 동작')],
 [('GMR','ΔR/R = (R_AP − R_P)/R_P, 다층박막 약 70 %'),('원리','spin-dependent scattering: 자화와 같은 스핀 → 산란 적음'),('두께','평균자유행정 수십 nm → 각 층 10 nm 이하'),('스핀 밸브','반강자성체로 고정층 pinning, 자유층만 회전 → 비대칭'),('SQUID','조셉슨 접합 2개 + 초전도 링, 출력 전압이 Φ₀ 주기로 진동')],
 [('GMR의 원리를 평행·반평행 상태로 설명하라.','【비자성 금속박막이 두 개의 강자성 박막 사이에 샌드위치】. 【평행: 스핀 업 전자들은 경계에서 산란 없이 통과 → 평균자유행정이 길어지므로 저항이 작아짐】. 【반평행: 경계에서 모든 전자들이 산란 → 평균자유행정이 짧아지고 저항 증가】. 【이 현상은 스핀 의존성 산란(spin dependent scattering)에 기인】, AMR 수 %에 비해 【약 70 %】로 giant. 【각 박막의 두께는 10 nm 이하】여야 계면 산란 비중이 커짐.','두 자석층이 같은 방향이면 한 종류 전자에게 지름길이 생겨 저항이 작아요.'),
  ('다층막 GMR과 스핀 밸브 GMR의 차이는?','다층막: 【반강자성 층간 상호결합에 의해 반평행】 → 외부 자계로 평행 → 【저항의 변화는 인가자계의 크기에만 의존하고 부호에는 무관(대칭)】, 【약한 자계에서는 감도가 매우 낮다】. 스핀 밸브: 【반강자성체에 이웃한 강자성체(고정층)의 자화는 교환 상호작용에 의해 고정】, 자유층만 회전 → 【비대칭적인 자기저항 특성】.','다층막은 방향을 못 가리고, 스핀 밸브는 한 층을 고정해 방향까지 구분해요.'),
  ('조셉슨 접합과 DC 조셉슨 효과를 설명하라.','【2개의 초전도체를 얇은 절연막으로 분리시킨 구조】(Nb | AlOₓ | Nb). 【쿠퍼 쌍(Cooper pairs)이 절연박막을 터널링】. 【DC 조셉슨 효과: 임계전류 I_c까지는 접합 사이에 전압이 생기지 않고 전류가 흐름】, 【I_c를 초과하면 접합 양단에 전압이 발생】.','초전도체 사이 얇은 벽을 전자 쌍이 통과해서, 어느 전류까지는 전압 없이 흘러요.'),
  ('DC SQUID의 동작 원리를 설명하라.','【두 개의 조셉슨 접합을 초전도 링으로 연결】, 【바이어스 전류 I는 두 접합에 I/2씩】. 외부 자속이 증가하면 【loop 전류 J】가 생겨 【한 접합의 전류 I/2 + J가 임계전류에 도달 → 전압 발생】. 【차폐 전류는 자속이 Φ₀/2 증가할 때마다 방향을 바꾸며 임계전류도 자속의 함수로 진동】 → 【출력전압은 자속양자 Φ₀를 주기로 진동】, 【전압 변화를 모니터링해 자계 측정】. 【Calibration은 국부적인 선형 구간에서】. 【DC SQUID가 RF SQUID보다 자속 분해능이 높고 고감도】. 응용: 【MEG, MCG, 지질 탐사, NDE】.','자속이 아주 조금 변할 때마다 전압이 오르내려서, fT 수준 자기장(뇌 자기장)도 잴 수 있어요. 대신 극저온이 필요해요.')])

# ───────── Ⅳ 속도센서·금속탐지기 (13) ─────────
add('13-A','유도형 속도센서 vs 홀 속도센서',['V = −nΔΦ/Δt','렌츠','영구자석','저속','Schmitt trigger'],
 '유도형 = 자속 변화율 → 저속 출력↓, 전원 불필요 · 홀 = 자계 크기 → 저속 OK, Schmitt trigger로 디지털',
 [(W5,'p.5','Inductive speed sensor 구조'),(W5,'p.6–7','전자기 유도 · 렌츠 · 영구자석 역할'),(W5,'p.8','Speed vs 출력'),(W5,'p.9','고장 진단'),(W5,'p.11','Hall 디지털 속도센서')],
 [('유도기전력','V = −n ΔΦ/Δt'),('렌츠','유도 전류는 자속 변화를 방해하는 방향'),('영구자석','내부 자계 형성 → tooth 이동 시 큰 자속 변화'),('홀 디지털','출력이 자계 변화율과 무관 → 저속 OK · Schmitt trigger')],
 [('유도형 속도센서의 동작 원리와 영구자석의 역할은?','【Pole wheel의 teeth 표면에 ferromagnetic 물질】, 【Coil 내부에서 자기장의 변화는 코일에서 전압을 유도】, 【유도된 전압은 magnetic field 변화율·세기에 비례】(V = −nΔΦ/Δt, 【− 부호: 유도 전류는 자속의 변화를 방해하는 방향】). 【Permanent magnet은 센서 내부에 자기장을 형성】, 【이 자기장이 있어야 tooth의 이동에 따른 magnetic flux 변화가 빠르게 발생】, 【없으면 자기장이 매우 약해져 유효한 자속 변화가 작아진다】.','톱니가 자석 앞을 지나면 코일 속 자기장이 출렁여 전압이 생겨요. 자석이 없으면 출렁일 게 없어요.'),
  ('유도형 속도센서의 장단점과 홀 센서를 쓰는 이유는?','유도형: 【영구자석과 코일만을 사용하므로 전원이 불필요한 장점】이나 【저속회전에서는 출력이 현저히 작아지는 단점】(RPM↑ → 자속 변화율↑ → 유도기전력↑). 홀: 【Output signal is not affected by the rate of change of the magnetic field】 → 저속에서도 신호 → 【자동차 속도 센서에는 Hall 센서가 널리 사용】. 【Schmitt trigger converts the analog to the digital by comparing with fixed reference(hysteresis)】. 【Duty cycle이 일정하지 않아도 주기 또는 pulse frequency를 측정하면 속도를 계산】.','유도형은 느리면 신호가 거의 없고, 홀은 자기장 "크기"를 보니 느려도 돼요.'),
  ('아날로그 속도센서의 주요 고장과 진단법 두 가지를 쓰라.','【코일 단락: 출력 전압이 매우 낮거나 없음 → 코일 저항 측정】. 【센서 자석 약화: 저속에서 신호 검출 불량 → 출력 파형을 정상 센서와 비교】. 【Air gap 내 금속 분말: 자기장 왜곡·노이즈 → 육안 점검·청소】. 【Tooth 파손: 특정 위치 신호 누락 → 파형 확인】. 코일 저항 【약 500~1,500 Ω】, air gap 【약 0.8~1.5 mm】.','코일·자석·공극·톱니, 네 군데를 봐요.')])

add('13-B','금속탐지기 구성 · 진폭 검출 · 설계 선택',['LC tank','와전류','Z = R_eff + jωL_eff','진폭','shielded'],
 'LC 발진 → 코일 AC 자계 → 금속 와전류 → 코일 임피던스 변화 → 진폭 검출 · 저항 변화 > 주파수 변화 · 낮은 f = 멀리·큰 것',
 [(W5,'p.15–16','구성도·동작원리'),(W5,'p.17–18','LC tank · 동작 주파수·코어'),(W5,'p.20','EM shielding'),(W5,'p.23','임피던스 변화 · 진폭 검출이 유효'),(W5,'p.29–30','측정 거리')],
 [('구성','LC Tank Oscillator → Sensor Coil → Target(Eddy) → Amplitude Detection/Demodulator → Output'),('공진','f = 1/(2π√LC)'),('검출','Z = R_eff + jωL_eff 변화 → 전류 진폭 변화'),('주파수','낮음 = 큰 타깃·장거리 / 높음 = 작은 타깃'),('차폐','Shielded = 전면 집중·정확 / Unshielded = 넓은 영역·긴 거리')],
 [('유도형 근접센서(금속탐지기)의 구성과 동작 원리를 설명하라.','【LC Tank Oscillator → 고주파 AC 발진】, 【Sensor Coil → 고주파 교류 자기장 생성】, 【Target Metal → 와전류(Eddy Current) 발생 → 2차 자기장 형성 → 센서 코일의 임피던스 및 인덕턴스 변화】, 【Amplitude Detection/Demodulator → 발진 진폭 변화 검출 및 복조】, 【Output Circuit → 기준값과 비교하여 ON/OFF 또는 DC 출력】.','코일이 뿌린 자기장을 금속이 빨아들이면 발진이 작아지는 걸 잡아요.'),
  ('금속 검출에 주파수 변화보다 진폭 검출이 유효한 이유는?','【와전류에 의한 금속의 Joule heating 발생 → 코일에서 바라본 유효저항 R_eff 증가】, 【유효 인덕턴스 L_eff 변화】 → 【임피던스 Z = R_eff + jωL_eff 변화 → 코일 전류 변화】. 【철, 알루미늄, 황동, 스테인리스강 등을 검출 대상으로 하는 경우 주파수 변화보다 저항성분의 변화가 더 크다. 따라서 발진 전압의 진폭을 검출하는 것이 발진 주파수 검출보다 훨씬 유효】.','금속이 오면 에너지를 뺏겨서(저항 증가) 진폭이 줄어드는 게 가장 크게 보여요.'),
  ('동작 주파수, 코어, 차폐를 어떻게 선택하는가?','주파수: 【낮은 주파수 → 큰 금속 타깃 및 장거리 검출】, 【높은 주파수 → 작은 금속 타깃 및 미세한 변화】. 코어: 【Magnetic core(NiFe) → 자속 집중, 인덕턴스·감도↑, 고주파 손실↑】 / 【Air coil → 손실·포화 없어 고주파·소형 금속 검출】. 차폐: 【Shielded → 자기장을 전면으로 집중, 검출 영역 좁고 정확한 위치 검출】 / 【Unshielded → 측면으로 넓게 퍼져 더 긴 검출 거리】. 【Magnetic core, shielded 센서가 긴 리딩거리를 제공】.','멀리 보려면 낮은 주파수와 코어, 작은 걸 보려면 높은 주파수예요.')])

add('13-C','와전류 · 침투 깊이 · 환경 간섭',['eddy current','skin depth','μ₀','비자성','permeability ~1'],
 '와전류 = 변하는 자계를 방해하는 2차 자계 · δ = 1/√(πfμσ), 두께 > δ 필요 · 자기장은 흙·물·오일 그대로 통과',
 [(W5,'p.21–22','Eddy current 방향·자속 감소'),(W5,'p.24','금속 종류에 따른 감도'),(W5,'p.25–27','Detectable minimum metal depth · skin depth'),(W5,'p.28','오염 환경 간섭')],
 [('와전류','변화하는 자계 → 금속 내부 순환 전류 → 변화를 방해하는 2차 자계'),('침투 깊이','δ = 1/√(π f μ σ), μ = 재료 투자율(H/m)'),('검출 조건','검출물체 두께 > δ → 박막 검출 곤란'),('감도','전도도 높을수록↑ · 비금속 불가 · 자성체는 와전류↓지만 거리 길다'),('오염','투자율 ≈ 1 → 손실 없이 통과')],
 [('와전류(eddy current)란 무엇이며 어떤 방향으로 흐르는가?','【변화하는 외부 자기장에 의해 금속 내부에 와전류가 유도】, 【와전류는 외부 자기장의 변화에 대항하는 방향의 2차 자기장을 생성】. 【N극이 금속 타깃에 접근하면 와전류는 접근하는 N극을 밀어내는 방향(금속 표면에 N극 형성)】, 【멀어지면 감소하는 자기선속을 유지하려는 방향(S극 형성)】. 【같은 자속을 유지하려면 회로에 더 큰 전류를 흘려야 한다】.','금속 속 소용돌이 전류는 언제나 변화를 방해해요. 렌츠 법칙이에요.'),
  ('검출 가능한 최소 금속 두께는 어떻게 정해지며, 박막을 검출하기 어려운 이유는?','【와전류가 발생하는 검출물체의 최소 두께, 즉 침투 깊이는 skin depth 식 δ = 1/√(πfμσ)】, 【μ는 재료의 permeability(H/m), relative permeability가 아님】. 【효과적인 동작을 위해서는 검출물체의 두께가 이 침투깊이보다는 두꺼워야 한다】 → 【와전류 센서는 금속박막 검출에는 사용이 곤란】. 주파수↑ → δ↓.','교류 자기장은 금속 표면 근처까지만 들어가요. 그보다 얇으면 와전류가 제대로 안 생겨요.'),
  ('금속 종류에 따른 감도와, 오염 환경에 강한 이유는?','【Detection sensitivity depends on the target material, higher for materials with higher electrical conductivity】. 【Non-metallic objects cannot be detected】. 【Magnetic materials: eddy current itself is significantly reduced; however detection sensitivity remains good and effective detection distance is relatively long】. 【Contaminants don’t interfere: resistant to dirt, dust, smoke, oil, grease】 — 【자기장은 흙, 수분, 오일, smoke gas, 나뭇잎, 돌, non-magnetic 금속에서 손실없이 그대로 통과(permeability ~1)】.','전기가 잘 통할수록 잘 잡히고, 먼지·기름은 자기장이 그냥 통과해서 상관없어요.')])

# ───────── Ⅴ 가속도·진동센서 (15) ─────────
add('15-B','측정 원리 · 차동 용량식 · 설계조건',['F = ma','x = ma/k','C₁ = εA/(d−x)','진공 패키징'],
 'a → F = ma → x = ma/k → C₁↑ C₂↓ → ΔC = C₁ − C₂ ≈ 2εAΔx/d² → V_o · 큰 g = high k·low m, gap > 진폭, 진공',
 [(W6,'슬라이드','How to measure acceleration · 단위 g'),(W6,'슬라이드','차동 용량식 · Capacitance changes'),(W6,'슬라이드','설계조건(Substrate, Proof-mass, gap, 진공 패키징)'),(W6,'슬라이드','제작기술 고려사항')],
 [('원리','F = ma → proof mass 변위 → 정전용량 변화 → 전압'),('차동','C₁ = εA/(d−x)↑, C₂ = εA/(d+x)↓, ΔC ≈ 2εAΔx/d²'),('설계','proof mass ≤ 0.1 g · 큰 가속도 = high k, lower m · gap > 최대 진폭 · 두꺼운 mass = 응력↓'),('패키징','진공 없으면 air damping·습도로 성능 제한')],
 [('가속도센서가 가속도를 측정하는 원리를 설명하라.','【뉴턴의 제2법칙 F = ma】, 【가속도 a를 경험하면 질량체(proof mass)에 힘이 작용】 → 【질량체가 고정 전극에 대해 변위】 → 【전극 사이의 정전용량이 변화】 → 【전압으로 변환되며 이 전압은 가속도에 비례】. 【질량체의 변위를 감지함으로써 가속도를 간접적으로 측정】. Hooke 법칙 F = kx → x = ma/k.','가속도가 생기면 매달린 추가 밀려요. 밀린 거리를 전기로 재요.'),
  ('차동 용량식(differential capacitive) 검출을 식으로 설명하라.','【가동전극은 두 고정전극 사이의 중심】, x = 0이면 【C₁ = C₂ = C₀ = εA/d】. 변위 x: 【C₁ = εA/(d−x), C₂ = εA/(d+x)】, Δx ≪ d이면 【ΔC = εA(2Δx)/d²】. 【질량의 변위 x는 두 정전용량의 차(C₁ − C₂)로부터 구해진다】. 【현재 MEMS 가속도 센서의 대부분은 차동 용량식】.','한쪽 간격은 좁아지고 반대쪽은 넓어져요. 그 차이를 읽어요.'),
  ('가속도센서 설계조건을 쓰라.','【Substrate: low parasitic capacitance, low temperature coefficient of expansion】. 【Proof-mass weight is very light: no more than 0.1 g】. 【측정하려는 가속도값이 크다면 high k(stiff beam), lower m】. 【Capacitor gap은 진동의 최대 진폭보다 커야】. 【No buckling, no mechanical stress → thicker proof-mass lowers stress】. 【Vacuum packaging: 없으면 gas(air) damping effect와 humidity effect로 성능이 크게 제한】.','큰 충격을 재려면 단단한 스프링과 가벼운 추, 전극은 안 부딪힐 간격, 공기는 빼요.')])

add('15-C','주요 파라미터 · Zero-g · 대역폭 · 노이즈 밀도',['Sensitivity V/g','full-scale','Zero-g','bandwidth','g/√Hz'],
 'Zero-g = (+1g + −1g)/2 · 대역폭 수백 Hz = 스프링 + 내부 공기 damping · 노이즈 밀도 = σ/감도/√BW',
 [(W6,'슬라이드','주요 파라미터'),(W6,'슬라이드','Sensitivity, Measurement range'),(W6,'슬라이드','Zero g output voltage'),(W6,'슬라이드','Bandwidth 40~1000 Hz'),(W6,'슬라이드','Noise Density 예시')],
 [('감도','mV/g, 입력 기계적 변화당 출력 변화'),('측정범위','최소 검출 진폭 ~ 출력 왜곡 전 최대 [g]'),('Zero-g','[Out(+1g) + Out(−1g)]/2'),('대역폭','응답하는 진동 주파수 범위, 사람 동작 10~12 Hz → 40~60 Hz 충분'),('노이즈 밀도','0 g σ → ÷감도 → ÷√Hz')],
 [('Zero-g 출력은 어떻게 측정하는가?','【센서를 무중력 상태로 만드는 것이 아니라 지구의 중력 1 g를 기준으로 측정】. 【측정축을 중력 방향으로 정렬하여 +1 g 출력 측정, 180° 회전하여 −1 g 출력 측정】, 【Zero-g Output = [Output(@+1g) + Output(@−1g)]/2】. 【실제 센서는 Offset, 온도, 응력, 조립 상태 등에 의해 이상적인 값에서 벗어날 수 있음】.','똑바로 한 번, 뒤집어서 한 번 재고 평균을 내요.'),
  ('정전용량형 가속도센서의 대역폭이 수백 Hz로 제한되는 이유는?','【Bandwidth: the range of vibration frequencies to which the accelerometer responds】. 【For a capacitive accelerometer, the bandwidth is only a few hundred Hertz because of their physical geometry (spring) and the air trapped inside the IC that acts as a damper】. 【Humans cannot create body motion beyond 10~12 Hz → 40~60 Hz면 사람 동작 감지에 충분】.','스프링과 갇힌 공기가 빠른 흔들림을 못 따라가요.'),
  ('노이즈 밀도의 정의와 측정 방법을 쓰라.','【특정 주파수에서 센서 출력에 나타나는 노이즈의 크기를 주파수 대역으로 정규화한 값(단위 g/√Hz)】. 【0 g에서 출력 전압의 랜덤한 흔들림 측정 → 표준편차(RMS) → 감도[V/g]로 나누어 g RMS로 변환 → √Hz로 정규화】. 예: 감도 1 V/g, 노이즈 1 mV, BW 100 Hz → 0.1 mg/√Hz.','출력 떨림을 g로 바꾸고 대역폭 제곱근으로 나눠 공평하게 비교해요.'),
  ('측정범위(full-scale range)와 범위를 벗어나면 생기는 일은?','【the range between the smallest detectable amplitude to the largest amplitude before distorting the output signal】. 【센서 범위를 벗어난 경우 응답이 왜곡되거나 정확하지 않을 수 있음】. 진동 측정 범위는 【proof mass 최대 진폭에 좌우】, 【큰 진동을 감지하는 센서의 proof mass 질량은 낮은 편】.','추가 끝까지 밀리면 더 이상 못 재요.')])

add('15-D','압전형 가속도센서 · 진동센서 · 신호 분석',['q = dF','정적 불가','진동센서 = 고주파 가속도센서','FFT'],
 '압전: 힘 → 분극 → 전하 q = d·m·a, V = q/C · 정적 가속도 검출 불가 · 진동센서 = bandwidth↑ noise↓ 최적화 · 시간/주파수 영역',
 [(W6,'슬라이드','압전형 가속도센서 구조·장단점'),(W6,'슬라이드','q = dᵢⱼF = dᵢⱼma'),(W6,'슬라이드','진동센서 정의 · 가속도센서와 관계'),(W6,'슬라이드','시간 영역 · 주파수 영역 분석'),(W6,'슬라이드','가속도 → 속도 → 거리')],
 [('구조','압전소자를 베이스와 추 사이에 고정, 종효과'),('식','q = dᵢⱼF = dᵢⱼma, V = q/C'),('장단점','구조 간단·강도 큼 → 큰 가속도·충격 / 정적 가속도 검출 불가'),('진동센서','기본구조 동일, 고주파용, bandwidth↑ noise↓'),('분석','시간 영역: 크기·지속시간·과도 / 주파수 영역(FFT): 성분·진폭·필터링')],
 [('압전형 가속도센서의 원리와 장단점을 쓰라.','【평판 또는 원판 모양의 압전소자를 베이스와 추 사이에 고정시킨 구조, 압전현상의 종효과를 이용】. 【압전결정에 힘을 가하면 내부에서 전기 분극이 발생하여 결정 표면에 전하】, 【q = dᵢⱼF = dᵢⱼma(dᵢⱼ: 압전계수 C/N)】, 출력전압 V = q/C. 【구조가 간단하고 기계적 강도도 커서 큰 가속도 및 충격 계측에 적합】, 【정적인 가속도를 검출할 수 없다는 결점】.','누르면 전기가 나오는 결정이에요. 충격에는 좋지만 가만히 있는 가속도(중력)는 못 재요.'),
  ('진동센서와 가속도센서의 관계를 설명하라.','【진동: 기계 또는 구성요소의 평형 위치에 대한 움직임 또는 떨림, 단위 g】. 【진동센서는 가속도센서를 사용하여 측정: a(t) → proof mass의 움직임 → 진동의 크기와 주파수】. 【진동센서와 가속도센서는 기본구조가 동일】, 【진동센서는 고주파 가속도 센서라 볼 수 있으며 bandwidth와 frequency를 높이고 noise를 최소화하는 구조로 최적화】.','같은 센서인데 빠른 떨림용으로 다듬은 거예요.'),
  ('진동 신호의 시간 영역 분석과 주파수 영역 분석의 차이는?','【시간 영역: 시간에 따른 진동의 패턴과 과도 현상(Transient Event)을 식별, 크기(Magnitude)와 지속 시간(Duration) 확인】. 【주파수 영역(FFT): 각 주파수 성분과 그 진폭을 시각화하여 특정 진동 패턴과 주파수를 식별, 노이즈 및 원하지 않는 진동 성분을 필터링】.','언제 얼마나 흔들렸나는 시간 그래프, 무슨 주파수가 섞였나는 FFT예요.'),
  ('측정한 가속도에서 속도와 거리를 구하는 방법은?','【Time 1과 Time 2를 결정하고 a의 값을 평균 → 평균한 a 값에 시간차를 곱하여 속도】, 【두 시간 지점의 속도 v를 평균 → 시간을 곱하여 거리 → 앞에서 얻어진 거리에 합하여 총 이동거리】. 【두 시간대를 짧게 하여 정확도를 높인다】.','구간마다 평균 × 시간을 더해 가요. 간격이 짧을수록 정확해요.')])
